// Supervisor + worker hand-off interface — minimal contract.
import Anthropic from '@anthropic-ai/sdk';

export interface Worker {
  id: string;
  blurb: string;
  systemPrompt: string;
  tools: Anthropic.Tool[];
}

export interface SupervisorDecision {
  workerId: string;
  reason: string;
}

export async function supervise(
  client: Anthropic,
  question: string,
  workers: Worker[],
): Promise<SupervisorDecision> {
  const res = await client.messages.create({
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 256,
    system: 'Route the user question to exactly one worker.',
    tools: [{
      name: 'route',
      description: 'Pick the best worker.',
      input_schema: {
        type: 'object',
        properties: {
          worker_id: { type: 'string', enum: workers.map(w => w.id) },
          reason: { type: 'string' },
        },
        required: ['worker_id', 'reason'],
      },
    }],
    tool_choice: { type: 'tool', name: 'route' },
    messages: [{
      role: 'user',
      content: `Workers:\n${workers.map(w => `- ${w.id}: ${w.blurb}`).join('\n')}\n\nQuestion: ${question}`,
    }],
  });
  const tu = res.content.find(b => b.type === 'tool_use');
  if (!tu || tu.type !== 'tool_use') throw new Error('No routing decision');
  const { worker_id, reason } = tu.input as { worker_id: string; reason: string };
  return { workerId: worker_id, reason };
}
